import {existsSync,readFileSync,writeFileSync,mkdirSync} from 'node:fs';import {contained,hash} from '../../safety.js';import {fetchSource,releaseHeadings} from './sources.js';import type {Config} from '../../config.js';import type {Evidence} from '../../models.js';
export const sdkRepositories:Record<string,string>={python:'stripe-python',go:'stripe-go',java:'stripe-java',csharp:'stripe-dotnet',php:'stripe-php',ruby:'stripe-ruby'};
export async function collectSDKSource(root:string,language:string,offline:boolean,config:Config,fetcher:typeof fetch=fetch){
 const repository=sdkRepositories[language];if(!repository||!config.vendors.stripe.enabled)return {evidence:[] as Evidence[],releases:[] as string[],newlyObserved:[] as string[],unclassified:[] as string[]};
 const url=`https://raw.githubusercontent.com/stripe/${repository}/master/CHANGELOG.md`;const path=contained(root,`.changelume/cache/sdk-${language}.json`);let text:string|undefined,origin:Evidence['origin']='network';
 try{const cache=JSON.parse(readFileSync(path,'utf8'));if(cache.url===url&&typeof cache.text==='string'&&cache.text.length<=2000000&&hash(cache.text)===cache.sha256&&(offline||Date.now()-cache.fetchedAt>=0&&Date.now()-cache.fetchedAt<3600000)){text=cache.text;origin='cache';}}catch{/* Disposable cache. */}
 if(!text){if(offline)return {evidence:[] as Evidence[],releases:[],newlyObserved:[],unclassified:[language+': offline; no cached official SDK changelog. Online scan is required to observe releases. No automatic migration recipe is inferred.']};text=await fetchSource(url,config.sources,fetcher);releaseHeadings(text);mkdirSync(contained(root,'.changelume/cache'),{recursive:true});writeFileSync(path,JSON.stringify({url,text,sha256:hash(text),fetchedAt:Date.now()}));}
 const releases=releaseHeadings(text),observations=contained(root,`.changelume/observations/sdk-${language}.json`);let previous:string[]=[];try{const data=JSON.parse(readFileSync(observations,'utf8'));if(Array.isArray(data.releases)&&data.releases.every((r:unknown)=>typeof r==='string'))previous=data.releases;}catch{/* First observation. */}
 mkdirSync(contained(root,'.changelume/observations'),{recursive:true});writeFileSync(observations,JSON.stringify({releases,sha256:hash(text)}));return {evidence:[{url,sha256:hash(text),origin,release:'observed '+language+' SDK changelog'}] as Evidence[],releases,newlyObserved:releases.filter(r=>!previous.includes(r)),unclassified:[...(offline?[language+': cached offline source; freshness unverified.']:[]),...releases.slice(0,20).map(r=>language+' SDK '+r+': observed; semantic impact unclassified, manual review required.')]};
}
